import torch
import avelang
import avelang.language as al

# Map C register layout: set A=[1,2,3,4], B varies
@avelang.jit
def test(out: al.Tensor((16,), al.f32), which_b: al.i32):
    tid = al.thread_id(0)
    a_bf16 = al.make_local((4,), al.bf16)
    b_bf16 = al.make_local((4,), al.bf16)
    c_f32 = al.make_local((16,), al.f32)

    if tid == 0:
        a_bf16[0] = al.convert(1.0, al.bf16)
        a_bf16[1] = al.convert(2.0, al.bf16)
        a_bf16[2] = al.convert(3.0, al.bf16)
        a_bf16[3] = al.convert(4.0, al.bf16)
    else:
        for i in al.range(4):
            a_bf16[i] = al.convert(0.0, al.bf16)

    for i in al.range(4):
        if i == which_b:
            b_bf16[i] = al.convert(1.0, al.bf16)
        else:
            b_bf16[i] = al.convert(0.0, al.bf16)

    for i in al.range(16):
        c_f32[i] = al.convert(0.0, al.f32)

    a_u32 = al.view(a_bf16, al.Tensor((2,), al.u32))
    b_u32 = al.view(b_bf16, al.Tensor((2,), al.u32))
    c_f32 = al.amdgpu.mfma_32x32x8_bf16_f32(a_u32, b_u32, c_f32)

    if tid == 0:
        for i in al.range(16):
            out[i] = c_f32[i]

for which_b in range(4):
    t = torch.zeros(16, device='cuda', dtype=torch.float32)
    test[lambda: ((1,1,1), (64,1,1))](t, which_b)
    print(f"B[{which_b}]=1: {t.tolist()}")
